+function deferred() {
+	let resolve;
+	const promise = new Promise(r => {
+		resolve = r;
+	});
+	return { promise, resolve };
+}
+
+const first = deferred();
+
+export default {
+	props: {
+		promise: first.promise
+	},
+
+	async test({ assert, component, target, raf }) {
+		first.resolve(['a', 'b']);
+		await first.promise;
+		assert.htmlEqual(target.innerHTML, '<div>a</div><div>b</div>');
+
+		const second = deferred();
+		component.promise = second.promise;
+		second.resolve(['c', 'd']);
+		await second.promise;
+		assert.equal(target.querySelectorAll('div').length, 4);
+
+		raf.tick(100);
+		assert.htmlEqual(target.innerHTML, '<div>c</div><div>d</div>');
+
+		const third = deferred();
+		component.promise = third.promise;
+		third.resolve(['e', 'f']);
+		await third.promise;
+
+		raf.tick(200);
+		assert.htmlEqual(target.innerHTML, '<div>e</div><div>f</div>');
+	}
+};
